/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["cpp"]=g.BC_LEI_REVISAO["cpp"]||{};g.BC_LEI_REVISAO["cpp"][20]=[{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal — art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cpp:581","law":"cpp","ref":"581","label":"CPP — art. 581","paragraphs":["Art. 581. Caberá recurso, no sentido estrito, da decisão, despacho ou sentença:","I - que não receber a denúncia ou a queixa;","II - que concluir pela incompetência do juízo;","III - que julgar procedentes as exceções, salvo a de suspeição;","IV - que pronunciar o réu; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - que conceder, negar, arbitrar, cassar ou julgar inidônea a fiança, indeferir requerimento de prisão preventiva ou revogá-la, conceder liberdade provisória ou relaxar a prisão em flagrante; (Inciso com redação dada pela Lei nº 7.780, de 22/6/1989)","VI - (Revogado pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VII - que julgar quebrada a fiança ou perdido o seu valor;","VIII - que decretar a prescrição ou julgar, por outro modo, extinta a punibilidade;","IX - que indeferir o pedido de reconhecimento da prescrição ou de outra causa extintiva da punibilidade;","X - que conceder ou negar a ordem de habeas corpus;","XI - que conceder, negar ou revogar a suspensão condicional da pena;","XII - que conceder, negar ou revogar livramento condicional;","XIII - que anular o processo da instrução criminal, no todo ou em parte;","XIV - que incluir jurado na lista geral ou desta o excluir;","XV - que denegar a apelação ou a julgar deserta;","XVI - que ordenar a suspensão do processo, em virtude de questão prejudicial;","XVII - que decidir sobre a unificação de penas;","XVIII - que decidir o incidente de falsidade;","XIX - que decretar medida de segurança, depois de transitar a sentença em julgado;","XX - que impuser medida de segurança por transgressão de outra;","XXI - que mantiver ou substituir a medida de segurança, nos casos do art. 774;","XXII - que revogar a medida de segurança;","XXIII - que deixar de revogar a medida de segurança, nos casos em que a lei admita a revogação;","XXIV - que converter a multa em detenção ou em prisão simples;","XXV - que recusar homologação à proposta de acordo de não persecução penal, previsto no art. 28-A desta Lei. (Inciso acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:584","law":"cpp","ref":"584","label":"CPP — art. 584","paragraphs":["Art. 584. Os recursos terão efeito suspensivo nos casos de perda da fiança, de concessão de livramento condicional e dos ns. XV, XVII e XXIV do art. 581.","§ 1º Ao recurso interposto de sentença de impronúncia ou no caso do nº VIII do art. 581, aplicar-se-á o disposto nos arts. 596 e 598.","§ 2º O recurso da pronúncia suspenderá tão-somente o julgamento.","§ 3º O recurso do despacho que julgar quebrada a fiança suspenderá unicamente o efeito de perda da metade do seu valor.","§ 4º No caso previsto no inciso V do caput do art. 581, sem prejuízo do disposto no art. 589 deste Código, a qualquer tempo, até o julgamento, o recorrente poderá pedir ao Tribunal ad quem concessão de efeito suspensivo ou ativo ao recurso interposto, demonstrando a relevância dos motivos, a plausibilidade do direito alegado e a probabilidade de dano irreparável ou de difícil reparação, durante a tramitação. (Parágrafo acrescido pela Lei nº 15.358, de 24/3/2026)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:589","law":"cpp","ref":"589","label":"CPP — art. 589","paragraphs":["Art. 589. Com a resposta do recorrido ou sem ela, será o recurso concluso ao juiz, que, dentro de dois dias, reformará ou sustentará o seu despacho, mandando instruir o recurso com os traslados que lhe parecerem necessários.","Parágrafo único. Se o juiz reformar o despacho recorrido, a parte contrária, por simples petição, poderá recorrer da nova decisão, se couber recurso, não sendo mais lícito ao juiz modificá-la. Neste caso, independentemente de novos arrazoados, subirá o recurso nos próprios autos ou em traslado."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:593","law":"cpp","ref":"593","label":"CPP — art. 593","paragraphs":["Art. 593. Caberá apelação no prazo de cinco dias: (“Caput” do artigo com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","I - das sentenças definitivas de condenação ou absolvição proferidas por Juiz singular; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","II - das decisões definitivas, ou com força de definitivas, proferidas por Juiz singular, nos casos não previstos no capítulo anterior; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","III - das decisões do Tribunal do Júri, quando: (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","a) ocorrer nulidade posterior à pronúncia; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","b) for a sentença do Juiz Presidente contrária à lei expressa ou à decisão dos jurados; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","c) houver erro ou injustiça no tocante à aplicação da pena ou da medida de segurança; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","d) for a decisão dos jurados manifestamente contrária à prova dos autos. (Alínea acrescida pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 1º Se a sentença do Juiz Presidente for contrária à lei expressa ou divergir das respostas dos jurados aos quesitos, o Tribunal ad quem fará a devida retificação. (Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 2º Interposta a apelação com fundamento no nº III, letra c , deste artigo, o Tribunal ad quem, se lhe der provimento retificará a aplicação da pena ou da medida de segurança. (Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 3º Se a apelação se fundar no nº III, letra d, deste artigo, e o Tribunal ad quem se convencer de que a decisão dos jurados é manifestamente contrária à prova dos autos, dar-lhe-á provimento para sujeitar o réu a novo julgamento; não se admite, porém, pelo mesmo motivo, segunda apelação.","(Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 4º Quando cabível a apelação, não poderá ser usado o recurso em sentido estrito, ainda que somente de parte da decisão se recorra. (Parágrafo único transformado em § 4º pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:598","law":"cpp","ref":"598","label":"CPP — art. 598","paragraphs":["Art. 598. Nos crimes de competência do Tribunal do Júri, ou do juiz singular, se da sentença não for interposta apelação pelo Ministério Público no prazo legal, o ofendido ou qualquer das pessoas enumeradas no art. 31, ainda que não se tenha habilitado como assistente, poderá interpor apelação, que não terá, porém, efeito suspensivo.","Parágrafo único. O prazo para interposição desse recurso será de quinze dias e correrá do dia em que terminar o do Ministério Público."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:609","law":"cpp","ref":"609","label":"CPP — art. 609","paragraphs":["Art. 609. Os recursos, apelações e embargos serão julgados pelos Tribunais de Justiça, Câmaras ou Turmas criminais, de acordo com a competência estabelecida nas leis de organização judiciária. (“Caput” do artigo com redação dada pela Lei nº 1.720-B, de 3/11/1952)","Parágrafo único. Quando não for unânime a decisão de segunda instância, desfavorável ao réu, admitem-se embargos infringentes e de nulidade, que poderão ser apostos dentro de 10 (dez) dias, a contar da publicação de acórdão, na forma do artigo 613. Se o desacordo for parcial, os embargos serão restritos à matéria objeto de divergência. (Parágrafo único acrescido pela Lei nº 1.720-B, de 3/11/1952)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"lep:197","law":"lep","ref":"197","label":"LEP — art. 197","paragraphs":["Art. 197. Das decisões proferidas pelo juiz caberá recurso de agravo, sem efeito suspensivo."],"url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html"},{"key":"cpp:621","law":"cpp","ref":"621","label":"CPP — art. 621","paragraphs":["Art. 621. A revisão dos processos findos será admitida:","I - quando a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos;","II - quando a sentença condenatória se fundar em depoimentos, exames ou documentos comprovadamente falsos;","III - quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:640","law":"cpp","ref":"640","label":"CPP — art. 640","paragraphs":["Art. 640. A carta testemunhável será requerida ao escrivão, ou ao secretário do tribunal, conforme o caso, nas quarenta e oito horas seguintes ao despacho que denegar o recurso, indicando o requerente as peças do processo que deverão ser trasladadas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:586","law":"cpp","ref":"586","label":"CPP — art. 586","paragraphs":["Art. 586. O recurso voluntário poderá ser interposto no prazo de cinco dias.","Parágrafo único. No caso do art. 581, XIV, o prazo será de vinte dias, contado da data da publicação definitiva da lista de jurados."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:588","law":"cpp","ref":"588","label":"CPP — art. 588","paragraphs":["Art. 588. Dentro de dois dias, contados da interposição do recurso, ou do dia em que o escrivão, extraído o traslado, o fizer com vista ao recorrente, este oferecerá as razões e, em seguida, será aberta vista ao recorrido por igual prazo.","Parágrafo único. Se o recorrido for o réu, será intimado do prazo na pessoa do defensor."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:577","law":"cpp","ref":"577","label":"CPP — art. 577","paragraphs":["Art. 577. O recurso poderá ser interposto pelo Ministério Público, ou pelo querelante, ou pelo réu, seu procurador ou seu defensor.","Parágrafo único. Não se admitirá, entretanto, recurso da parte que não tiver interesse na reforma ou modificação da decisão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:416","law":"cpp","ref":"416","label":"CPP — art. 416","paragraphs":["Art. 416. Contra a sentença de impronúncia ou de absolvição sumária caberá apelação. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:583","law":"cpp","ref":"583","label":"CPP — art. 583","paragraphs":["Art. 583. Subirão nos próprios autos os recursos:","I - quando interpostos de oficio;","II - nos casos do art. 581, ns. I, III, IV, VI, VIII e X;","III - quando o recurso não prejudicar o andamento do processo.","Parágrafo único. O recurso da pronúncia subirá em traslado, quando, havendo dois ou mais réus, qualquer deles se conformar com a decisão ou todos não tiverem sido ainda intimados da pronúncia."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:587","law":"cpp","ref":"587","label":"CPP — art. 587","paragraphs":["Art. 587. Quando o recurso houver de subir por instrumento, a parte indicará, no respectivo termo, ou em requerimento avulso, as peças dos autos de que pretenda traslado.","Parágrafo único. O traslado será extraído, conferido e concertado no prazo de cinco dias, e dele constarão sempre a decisão recorrida, a certidão de sua intimação, se por outra forma não for possível verificar-se a oportunidade do recurso, e o termo de interposição."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:590","law":"cpp","ref":"590","label":"CPP — art. 590","paragraphs":["Art. 590. Quando for impossível ao escrivão extrair o traslado no prazo da lei, poderá o juiz prorrogá-lo até o dobro."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:591","law":"cpp","ref":"591","label":"CPP — art. 591","paragraphs":["Art. 591. Os recursos serão apresentados ao juiz ou tribunal ad quem, dentro de cinco dias da publicação da resposta do juiz a quo, ou entregues ao Correio dentro do mesmo prazo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:592","law":"cpp","ref":"592","label":"CPP — art. 592","paragraphs":["Art. 592. Publicada a decisão do juiz ou do tribunal ad quem, deverão os autos ser devolvidos, dentro de cinco dias, ao juiz a quo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:600","law":"cpp","ref":"600","label":"CPP — art. 600","paragraphs":["Art. 600. Assinado o termo de apelação, o apelante e, depois dele, o apelado terão o prazo de oito dias cada um para oferecer razões, salvo nos processos de contravenção, em que o prazo será de três dias.","§ 1º Se houver assistente, este arrazoará, no prazo de três dias, após o Ministério Público.","§ 2º Se a ação penal for movida pela parte ofendida, o Ministério Público terá vista dos autos, no prazo do parágrafo anterior.","§ 3º Quando forem dois ou mais os apelantes ou apelados, os prazos serão comuns.","§ 4º Se o apelante declarar, na petição ou no termo, ao interpor a apelação, que deseja arrazoar na Superior Instância serão os autos remetidos ao Tribunal ad quem onde será aberta vista às partes, observados os prazos legais, notificadas as partes pela publicação oficial. (Parágrafo acrescido pela Lei nº 4.336, de 1º/6/1964)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:806","law":"cpp","ref":"806","label":"CPP — art. 806","paragraphs":["Art. 806. Salvo o caso do art. 32, nas ações intentadas mediante queixa, nenhum ato ou diligência se realizará, sem que seja depositada em cartório a importância das custas.","§ 1º Igualmente, nenhum ato requerido no interesse da defesa será realizado, sem o prévio pagamento das custas, salvo se o acusado for pobre.","§ 2º A falta do pagamento das custas, nos prazos fixados em lei, ou marcados pelo juiz, importará renúncia à diligência requerida ou deserção do recurso interposto.","§ 3º A falta de qualquer prova ou diligência que deixe de realizar-se em virtude do não pagamento de custas não implicará a nulidade do processo, se a prova de pobreza do acusado só posteriormente foi feita."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:32","law":"cpp","ref":"32","label":"CPP — art. 32","paragraphs":["Art. 32. Nos crimes de ação privada, o juiz, a requerimento da parte que comprovar a sua pobreza, nomeará advogado para promover a ação penal.","§ 1º Considerar-se-á pobre a pessoa que não puder prover às despesas do processo, sem privar-se dos recursos indispensáveis ao próprio sustento ou da família.","§ 2º Será prova suficiente de pobreza o atestado da autoridade policial em cuja circunscrição residir o ofendido."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:31","law":"cpp","ref":"31","label":"CPP — art. 31","paragraphs":["Art. 31. No caso de morte do ofendido ou quando declarado ausente por decisão judicial, o direito de oferecer queixa ou prosseguir na ação passará ao cônjuge, ascendente, descendente ou irmão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:596","law":"cpp","ref":"596","label":"CPP — art. 596","paragraphs":["Art. 596. A apelação da sentença absolutória não impedirá que o réu seja posto imediatamente em liberdade.","Parágrafo único. A apelação não suspenderá a execução da medida de segurança aplicada provisoriamente (Artigo com redação dada pela Lei nº 5.941, de 22/11/1973)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:597","law":"cpp","ref":"597","label":"CPP — art. 597","paragraphs":["Art. 597. A apelação de sentença condenatória terá efeito suspensivo, salvo o disposto no art. 393, a aplicação provisória de interdições de direitos e de medidas de segurança (arts. 374 e 378), e o caso de suspensão condicional de pena."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:387","law":"cpp","ref":"387","label":"CPP — art. 387","paragraphs":["Art. 387. O juiz, ao proferir sentença condenatória:","I - mencionará as circunstâncias agravantes ou atenuantes definidas no Código Penal, e cuja existência reconhecer;","II - mencionará as outras circunstâncias apuradas e tudo o mais que deva ser levado em conta na aplicação da pena, de acordo com o disposto nos arts. 59 e 60 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal; (Inciso com redação dada pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","III - aplicará as penas de acordo com essas conclusões; (Inciso com redação dada pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","IV - fixará valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido; (Inciso com redação dada pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","V - atenderá, quanto à aplicação provisória de interdições de direitos e medidas de segurança, ao disposto no Título XI deste Livro;","VI - determinará se a sentença deverá ser publicada na íntegra ou em resumo e designará o jornal em que será feita a publicação (art. 73, § 1º, do Código Penal).","§ 1º O juiz decidirá, fundamentadamente, sobre a manutenção ou, se for o caso, a imposição de prisão preventiva ou de outra medida cautelar, sem prejuízo do conhecimento de apelação que vier a ser interposta. (Parágrafo único acrescido pela Lei nº 11.719, de 20/6/2008, transformado em § 1º e com redação dada pela Lei nº 12.736, de 30/11/2012)","§ 2º O tempo de prisão provisória, de prisão administrativa ou de internação, no Brasil ou no estrangeiro, será computado para fins de determinação do regime inicial de pena privativa de liberdade. (Parágrafo acrescido pela Lei nº 12.736, de 30/11/2012)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:492","law":"cpp","ref":"492","label":"CPP — art. 492","paragraphs":["Art. 492. Em seguida, o presidente proferirá sentença que: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - no caso de condenação: (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","a) fixará a pena-base; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","b) considerará as circunstâncias agravantes ou atenuantes alegadas nos debates; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","c) imporá os aumentos ou diminuições da pena, em atenção às causas admitidas pelo júri; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","d) observará as demais disposições do art. 387 deste Código; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","e) mandará o acusado recolher-se ou recomendá-lo-á à prisão em que se encontra, se presentes os requisitos da prisão preventiva, ou, no caso de condenação a uma pena igual ou superior a 15 (quinze) anos de reclusão, determinará a execução provisória das penas, com expedição do mandado de prisão, se for o caso, sem prejuízo do conhecimento de recursos que vierem a ser interpostos; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, e com nova redação dada pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","f) estabelecerá os efeitos genéricos e específicos da condenação; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - no caso de absolvição:","a) mandará colocar em liberdade o acusado se por outro motivo não estiver preso;","b) revogará as medidas restritivas provisoriamente decretadas;","c) imporá, se for o caso, a medida de segurança cabível. (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Se houver desclassificação da infração para outra, de competência do juiz singular, ao presidente do Tribunal do Júri caberá proferir sentença em seguida, aplicando-se, quando o delito resultante da nova tipificação for considerado pela lei como infração penal de menor potencial ofensivo, o disposto nos arts. 69 e seguintes da Lei nº 9.099, de 26 de setembro de 1995. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Em caso de desclassificação, o crime conexo que não seja doloso contra a vida será julgado pelo juiz presidente do Tribunal do Júri, aplicando-se, no que couber, o disposto no § 1º deste artigo. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º O presidente poderá, excepcionalmente, deixar de autorizar a execução provisória das penas de que trata a alínea e do inciso I do caput deste artigo, se houver questão substancial cuja resolução pelo tribunal ao qual competir o julgamento possa plausivelmente levar à revisão da condenação. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 4º A apelação interposta contra decisão condenatória do Tribunal do Júri a uma pena igual ou superior a 15 (quinze) anos de reclusão não terá efeito suspensivo. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 5º Excepcionalmente, poderá o tribunal atribuir efeito suspensivo à apelação de que trata o § 4º deste artigo, quando verificado cumulativamente que o recurso:","I - não tem propósito meramente protelatório; e","II - levanta questão substancial e que pode resultar em absolvição, anulação da sentença, novo julgamento ou redução da pena para patamar inferior a 15 (quinze) anos de reclusão. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 6º O pedido de concessão de efeito suspensivo poderá ser feito incidentemente na apelação ou por meio de petição em separado dirigida diretamente ao relator, instruída com cópias da sentença condenatória, das razões da apelação e de prova da tempestividade, das contrarrazões e das demais peças necessárias à compreensão da controvérsia. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:382","law":"cpp","ref":"382","label":"CPP — art. 382","paragraphs":["Art. 382. Qualquer das partes poderá, no prazo de dois dias, pedir ao juiz que declare a sentença, sempre que nela houver obscuridade, ambigüidade, contradição ou omissão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:619","law":"cpp","ref":"619","label":"CPP — art. 619","paragraphs":["Art. 619. Aos acórdãos proferidos pelos Tribunais de Apelação, câmaras ou turmas, poderão ser opostos embargos de declaração, no prazo de dois dias contados da sua publicação, quando houver na sentença ambigüidade, obscuridade, contradição ou omissão. (Artigo retificado no DOU de 24/10/1941)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:620","law":"cpp","ref":"620","label":"CPP — art. 620","paragraphs":["Art. 620. Os embargos de declaração serão deduzidos em requerimento de que constem os pontos em que o acórdão é ambíguo, obscuro, contraditório ou omisso.","§ 1º O requerimento será apresentado pelo relator e julgado, independentemente de revisão, na primeira sessão.","§ 2º Se não preenchidas as condições enumeradas neste artigo, o relator indeferirá desde logo o requerimento."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpc:1026","law":"cpc","ref":"1026","label":"CPC/2015 — art. 1026","paragraphs":["Art. 1.026. Os embargos de declaração não possuem efeito suspensivo e interrompem o prazo para a interposição de recurso.","§ 1º A eficácia da decisão monocrática ou colegiada poderá ser suspensa pelo respectivo juiz ou relator se demonstrada a probabilidade de provimento do recurso ou, sendo relevante a fundamentação, se houver risco de dano grave ou de difícil reparação.","§ 2º Quando manifestamente protelatórios os embargos de declaração, o juiz ou o tribunal, em decisão fundamentada, condenará o embargante a pagar ao embargado multa não excedente a dois por cento sobre o valor atualizado da causa.","§ 3º Na reiteração de embargos de declaração manifestamente protelatórios, a multa será elevada a até dez por cento sobre o valor atualizado da causa, e a interposição de qualquer recurso ficará condicionada ao depósito prévio do valor da multa, à exceção da Fazenda Pública e do beneficiário de gratuidade da justiça, que a recolherão ao final.","§ 4º Não serão admitidos novos embargos de declaração se os 2 (dois) anteriores houverem sido considerados protelatórios."],"url":"https://www2.camara.leg.br/legin/fed/lei/2015/lei-13105-16-marco-2015-780273-normaatualizada-pl.html"},{"key":"lep:179","law":"lep","ref":"179","label":"LEP — art. 179","paragraphs":["Art. 179. Transitada em julgado a sentença, o juiz expedirá ordem para a desinternação ou a liberação."],"url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html"},{"key":"cpp:639","law":"cpp","ref":"639","label":"CPP — art. 639","paragraphs":["Art. 639. Dar-se-á carta testemunhável:","I - da decisão que denegar o recurso;","II - da que, admitindo embora o recurso, obstar à sua expedição e seguimento para o juízo ad quem."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:641","law":"cpp","ref":"641","label":"CPP — art. 641","paragraphs":["Art. 641. O escrivão, ou o secretário do tribunal, dará recibo da petição à parte e, no prazo máximo de cinco dias, no caso de recurso no sentido estrito, ou de sessenta dias, no caso de recurso extraordinário, fará entrega da carta, devidamente conferida e concertada."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:642","law":"cpp","ref":"642","label":"CPP — art. 642","paragraphs":["Art. 642. O escrivão, ou o secretário do tribunal, que se negar a dar o recibo, ou deixar de entregar, sob qualquer pretexto, o instrumento, será suspenso por trinta dias. O juiz, ou o presidente do Tribunal de Apelação, em face de representação do testemunhante, imporá a pena e mandará que seja extraído o instrumento, sob a mesma sanção, pelo substituto do escrivão ou do secretário do tribunal.","Se o testemunhante não for atendido, poderá reclamar ao presidente do tribunal ad quem, que avocará os autos, para o efeito do julgamento do recurso e imposição da pena."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:643","law":"cpp","ref":"643","label":"CPP — art. 643","paragraphs":["Art. 643. Extraído e autuado o instrumento, observar-se-á o disposto nos arts. 588 a 592, no caso de recurso em sentido estrito, ou o processo estabelecido para o recurso extraordinário, se deste se tratar."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:644","law":"cpp","ref":"644","label":"CPP — art. 644","paragraphs":["Art. 644. O tribunal, câmara ou turma a que competir o julgamento da carta, se desta tomar conhecimento, mandará processar o recurso, ou, se estiver suficientemente instruída, decidirá logo, de meritis."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:645","law":"cpp","ref":"645","label":"CPP — art. 645","paragraphs":["Art. 645. O processo da carta testemunhável na instância superior seguirá o processo do recurso denegado."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:646","law":"cpp","ref":"646","label":"CPP — art. 646","paragraphs":["Art. 646. A carta testemunhável não terá efeito suspensivo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:622","law":"cpp","ref":"622","label":"CPP — art. 622","paragraphs":["Art. 622. A revisão poderá ser requerida em qualquer tempo, antes da extinção da pena ou após.","Parágrafo único. Não será admissível a reiteração do pedido, salvo se fundado em novas provas."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:626","law":"cpp","ref":"626","label":"CPP — art. 626","paragraphs":["Art. 626. Julgando procedente a revisão, o tribunal poderá alterar a classificação da infração, absolver o réu, modificar a pena ou anular o processo.","Parágrafo único. De qualquer maneira, não poderá ser agravada a pena imposta pela decisão revista."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:623","law":"cpp","ref":"623","label":"CPP — art. 623","paragraphs":["Art. 623. A revisão poderá ser pedida pelo próprio réu ou por procurador legalmente habilitado ou, no caso de morte do réu, pelo cônjuge, ascendente, descendente ou irmão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:631","law":"cpp","ref":"631","label":"CPP — art. 631","paragraphs":["Art. 631. Quando, no curso da revisão, falecer a pessoa, cuja condenação tiver de ser revista, o presidente do tribunal nomeará curador para a defesa."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:624","law":"cpp","ref":"624","label":"CPP — art. 624","paragraphs":["Art. 624. As revisões criminais serão processadas e julgadas: (“Caput” do artigo com redação dada pelo Decreto-Lei nº 504, de 18/3/1969)","I - pelo Supremo Tribunal Federal, quanto às condenações por ele proferidas; (Inciso com redação dada pelo Decreto-Lei nº 504, de 18/3/1969)","II - pelo Tribunal Federal de Recursos, Tribunais de Justiça ou de Alçada, nos demais casos. (Inciso com redação dada pelo Decreto-Lei nº 504, de 18/3/1969)","§ 1º No Supremo Tribunal Federal e no Tribunal Federal de Recursos o processo e julgamento obedecerão ao que for estabelecido no respectivo Regimento Interno. (Parágrafo único transformado em § 1º e com redação dada pelo Decreto-Lei nº 504, de 18/3/1969)","§ 2º Nos Tribunais de Justiça ou de Alçada, o julgamento será efetuado pelas Câmaras ou Turmas Criminais, reunidas em sessão conjunta, quando houver mais de uma, e, no caso contrário, pelo Tribunal pleno. (Parágrafo acrescido pelo Decreto-Lei nº 504, de 18/3/1969)","§ 3º Nos Tribunais onde houver quatro ou mais Câmaras ou Turmas Criminais, poderão ser constituídos dois ou mais Grupos de Câmaras ou Turmas para o julgamento de revisão, obedecido o que for estabelecido no respectivo Regimento Interno. (Parágrafo acrescido pelo Decreto-Lei nº 504, de 18/3/1969)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:625","law":"cpp","ref":"625","label":"CPP — art. 625","paragraphs":["Art. 625. O requerimento será distribuído a um relator e a um revisor, devendo funcionar como relator um desembargador que não tenha pronunciado decisão em qualquer fase do processo.","§ 1º O requerimento será instruído com a certidão de haver passado em julgado a sentença condenatória e com as peças necessárias à comprovação dos fatos argüidos.","§ 2º O relator poderá determinar que se apensem os autos originais, se daí não advier dificuldade à execução normal da sentença.","§ 3º Se o relator julgar insuficientemente instruído o pedido e inconveniente ao interesse da justiça que se apensem os autos originais, indeferi-lo-á in limine, dando recurso para as câmaras reunidas ou para o tribunal, conforme o caso (art. 624, parágrafo único).","§ 4º Interposto o recurso por petição e independentemente de termo, o relator apresentará o processo em mesa para o julgamento e o relatará, sem tomar parte na discussão.","§ 5º Se o requerimento não for indeferido in limine, abrir-se-á vista dos autos ao procurador-geral, que dará parecer no prazo de dez dias. Em seguida, examinados os autos, sucessivamente, em igual prazo, pelo relator e revisor, julgar-se-á o pedido na sessão que o presidente designar."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:630","law":"cpp","ref":"630","label":"CPP — art. 630","paragraphs":["Art. 630. O tribunal, se o interessado o requerer, poderá reconhecer o direito a uma justa indenização pelos prejuízos sofridos.","§ 1º Por essa indenização, que será liquidada no juízo cível, responderá a União, se a condenação tiver sido proferida pela justiça do Distrito Federal ou de Território, ou o Estado, se o tiver sido pela respectiva justiça.","§ 2º A indenização não será devida:","a) se o erro ou a injustiça da condenação proceder de ato ou falta imputável ao próprio impetrante, como a confissão ou a ocultação de prova em seu poder;","b) se a acusação houver sido meramente privada."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:582","law":"cpp","ref":"582","label":"CPP — art. 582","paragraphs":["Art. 582. Os recursos serão sempre para o Tribunal de Apelação, salvo nos casos dos ns. V, X e XIV.","Parágrafo único. O recurso, no caso do nº XIV, será para o presidente do Tribunal de Apelação."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:585","law":"cpp","ref":"585","label":"CPP — art. 585","paragraphs":["Art. 585. O réu não poderá recorrer da pronúncia senão depois de preso, salvo se prestar fiança, nos casos em que a lei a admitir."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:594","law":"cpp","ref":"594","label":"CPP — art. 594","paragraphs":["Art. 594. (Revogado pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:595","law":"cpp","ref":"595","label":"CPP — art. 595","paragraphs":["Art. 595. (Revogado pela Lei nº 12.403, de 4/5/2011, publicada no DOU de 5/5/2011, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:599","law":"cpp","ref":"599","label":"CPP — art. 599","paragraphs":["Art. 599. As apelações poderão ser interpostas quer em relação a todo o julgado, quer em relação a parte dele."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:601","law":"cpp","ref":"601","label":"CPP — art. 601","paragraphs":["Art. 601. Findos os prazos para razões, os autos serão remetidos à instância superior, com as razões ou sem elas, no prazo de cinco dias, salvo no caso do art. 603, segunda parte, em que o prazo será de trinta dias.","§ 1º Se houver mais de um réu, e não houverem todos sido julgados, ou não tiverem todos apelado, caberá ao apelante promover extração do traslado dos autos, o qual deverá ser remetido à instância superior no prazo de trinta dias, contado da data da entrega das últimas razões de apelação, ou do vencimento do prazo para a apresentação das do apelado.","§ 2º As despesas do traslado correrão por conta de quem o solicitar, salvo se o pedido for de réu pobre ou do Ministério Público."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:602","law":"cpp","ref":"602","label":"CPP — art. 602","paragraphs":["Art. 602. Os autos serão, dentro dos prazos do artigo anterior, apresentados ao tribunal ad quem ou entregues ao Correio, sob registro."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:603","law":"cpp","ref":"603","label":"CPP — art. 603","paragraphs":["Art. 603. A apelação subirá nos autos originais e, a não ser no Distrito Federal e nas comarcas que forem sede de Tribunal de Apelação, ficará em cartório traslado dos termos essenciais do processo referidos no art. 564, III."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:604","law":"cpp","ref":"604","label":"CPP — art. 604","paragraphs":["Art. 604. (Revogado pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:605","law":"cpp","ref":"605","label":"CPP — art. 605","paragraphs":["Art. 605. (Revogado pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:606","law":"cpp","ref":"606","label":"CPP — art. 606","paragraphs":["Art. 606. (Revogado pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:607","law":"cpp","ref":"607","label":"CPP — art. 607","paragraphs":["Art. 607. (Revogado pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:608","law":"cpp","ref":"608","label":"CPP — art. 608","paragraphs":["Art. 608. (Revogado pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:610","law":"cpp","ref":"610","label":"CPP — art. 610","paragraphs":["Art. 610. Nos recursos em sentido estrito, com exceção do de habeas corpus, e nas apelações interpostas das sentenças em processo de contravenção ou de crime a que a lei comine pena de detenção, os autos irão imediatamente com vista ao procurador-geral pelo prazo de cinco dias, e, em seguida, passarão, por igual prazo, ao relator, que pedirá designação de dia para o julgamento.","Parágrafo único. Anunciado o julgamento pelo presidente, e apregoadas as partes, com a presença destas ou à sua revelia, o relator fará a exposição do feito, e, em seguida, o presidente concederá, pelo prazo de dez minutos, a palavra aos advogados ou às partes que a solicitarem e ao procurador-geral, quando o requerer, por igual prazo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:611","law":"cpp","ref":"611","label":"CPP — art. 611","paragraphs":["Art. 611. (Revogado pelo Decreto-Lei nº 552, de 25/4/1969)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:612","law":"cpp","ref":"612","label":"CPP — art. 612","paragraphs":["Art. 612. Os recursos de habeas corpus, designado o relator, serão julgados na primeira sessão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:613","law":"cpp","ref":"613","label":"CPP — art. 613","paragraphs":["Art. 613. As apelações interpostas das sentenças proferidas em processos por crime a que a lei comine pena de reclusão, deverão ser processadas e julgadas pela forma estabelecida no art. 610, com as seguintes modificações:","I - exarado o relatório nos autos, passarão estes ao revisor, que terá igual prazo para o exame do processo e pedirá designação de dia para o julgamento; (Inciso retificado no DOU de 24/10/1941)","II - os prazos serão ampliados ao dobro;","III - o tempo para os debates será de um quarto de hora."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:614","law":"cpp","ref":"614","label":"CPP — art. 614","paragraphs":["Art. 614. No caso de impossibilidade de observância de qualquer dos prazos marcados nos arts. 610 e 613, os motivos da demora serão declarados nos autos."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:615","law":"cpp","ref":"615","label":"CPP — art. 615","paragraphs":["Art. 615. O tribunal decidirá por maioria de votos.","§ 1º Em todos os julgamentos em matéria penal ou processual penal em órgãos colegiados, havendo empate, prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado, ainda que, nas hipóteses de vaga aberta a ser preenchida, de impedimento, de suspeição ou de ausência, tenha sido o julgamento tomado sem a totalidade dos integrantes do colegiado. (Parágrafo com redação dada pela Lei nº 14.836, de 8/4/2024)","§ 2º O acórdão será apresentado à conferência na primeira sessão seguinte à do julgamento, ou no prazo de duas sessões, pelo juiz incumbido de lavrá-lo."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:616","law":"cpp","ref":"616","label":"CPP — art. 616","paragraphs":["Art. 616. No julgamento das apelações poderá o tribunal, câmara ou turma proceder a novo interrogatório do acusado, reinquirir testemunhas ou determinar outras diligências."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:617","law":"cpp","ref":"617","label":"CPP — art. 617","paragraphs":["Art. 617. O tribunal, câmara ou turma atenderá nas suas decisões ao disposto nos arts. 383, 386 e 387, no que for aplicável, não podendo, porém, ser agravada a pena, quando somente o réu houver apelado da sentença."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:618","law":"cpp","ref":"618","label":"CPP — art. 618","paragraphs":["Art. 618. Os regimentos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento dos recursos e apelações."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:627","law":"cpp","ref":"627","label":"CPP — art. 627","paragraphs":["Art. 627. A absolvição implicará o restabelecimento de todos os direitos perdidos em virtude da condenação, devendo o tribunal, se for caso, impor a medida de segurança cabível."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:628","law":"cpp","ref":"628","label":"CPP — art. 628","paragraphs":["Art. 628. Os regimentos internos dos Tribunais de Apelação estabelecerão as normas complementares para o processo e julgamento das revisões criminais."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:629","law":"cpp","ref":"629","label":"CPP — art. 629","paragraphs":["Art. 629. À vista da certidão do acórdão que cassar a sentença condenatória, o juiz mandará juntá-la imediatamente aos autos, para inteiro cumprimento da decisão."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:632","law":"cpp","ref":"632","label":"CPP — art. 632 (revogado)","paragraphs":["Arts. 632 a 636. (Revogados pela Lei nº 3.396, de 2/6/1958)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:633","law":"cpp","ref":"633","label":"CPP — art. 633 (revogado)","paragraphs":["Arts. 632 a 636. (Revogados pela Lei nº 3.396, de 2/6/1958)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:634","law":"cpp","ref":"634","label":"CPP — art. 634 (revogado)","paragraphs":["Arts. 632 a 636. (Revogados pela Lei nº 3.396, de 2/6/1958)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:635","law":"cpp","ref":"635","label":"CPP — art. 635 (revogado)","paragraphs":["Arts. 632 a 636. (Revogados pela Lei nº 3.396, de 2/6/1958)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:636","law":"cpp","ref":"636","label":"CPP — art. 636 (revogado)","paragraphs":["Arts. 632 a 636. (Revogados pela Lei nº 3.396, de 2/6/1958)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:637","law":"cpp","ref":"637","label":"CPP — art. 637","paragraphs":["Art. 637. O recurso extraordinário não tem efeito suspensivo, e uma vez arrazoados pelo recorrido os autos do traslado, os originais baixarão à primeira instância, para a execução da sentença."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:638","law":"cpp","ref":"638","label":"CPP — art. 638","paragraphs":["Art. 638. O recurso extraordinário e o recurso especial serão processados e julgados no Supremo Tribunal Federal e no Superior Tribunal de Justiça na forma estabelecida por leis especiais, pela lei processual civil e pelos respectivos regimentos internos. (Artigo com redação dada pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"}];})(window);
